#
 def nombre_exemplaires(nb_flyers:int) -> int:
    """ renvoie le nombre d’exemplaires qui seront réellement commandés. 

    Précondition : nb_flyers >= 0
    Exemple(s) :
    $$$ nombre_exemplaires(50)
    100
    $$$ nombre_exemplaires(125)
    500
    $$$ nombre_exemplaires(846)
    1000
    $$$ nombre_exemplaires(1250)
    2000
    $$$ nombre_exemplaires(5001)
    6000
    """
    if nb_flyers <= 100:
        return 100
    elif nb_flyers >= 101 and nb_flyers <= 500:
        return 500
    elif nb_flyers >= 501 and nb_flyers <= 1000:
        return 1000
    else:
        if nb_flyers % 1000 == 0:
            return nb_flyers
        else:    
            return ((nb_flyers +1000) // 1000) *1000

def montant_facture(nb_flyers : int)->float:
    """  renvoie le prix à payer pour ces flyers. 

    Précondition : nb_flyers >= 0
    Exemple(s) :
    $$$ montant_facture(100)
    30
    $$$ montant_facture(500)
    45.
    $$$ montant_facture(1000)
    50.
    $$$ montant_facture(3004)
    90.12
    """
    if nb_flyers >= 0 and nb_flyers <= 100:
        return round(nb_flyers * 0.3, 2)
    elif nb_flyers > 100 and nb_flyers <= 500:
        return round(nb_flyers * 0.09, 2)
    elif nb_flyers > 500 and nb_flyers <= 1000:
        return round(nb_flyers * 0.05, 2)
    elif nb_flyers > 1000 and nb_flyers <= 2000:
        return round(nb_flyers * 0.03, 2)
    else:
        return round(nb_flyers * 0.03, 2)

